	inline constexpr std::array<TrialDef, 5> kTrials{ {
		TrialDef{ "ward", "Ward of the Tongues", "Hold the runic circle at the altar", "Stand in the runic circle at the Echo Altar of {city}", "The Tongues who raised the Echo Altar of {city} sealed it with a circle of runes that only a living voice can hold open. Stand inside it while Alduin's echo summons the dead against you, thicker than any night before; step out and the runes fall quiet until you return. Hold the circle for {s} seconds.", { 0, 0, 0, 0, 0, 0 }, { 40, 50, 60, 75, 90, 105 } },
		TrialDef{ "culling", "The Culling", "Slay the risen within the city", "Slay the risen within {city}", "SLEN - Flesh. The first of Alduin's three words puts flesh back on the dead, and the altar answers by striking it off again. Put {n} of the risen down within {city} - every one the night conjures up counts.", { 40, 50, 60, 75, 90, 110 }, { 0, 0, 0, 0, 0, 0 } },
		TrialDef{ "unbroken", "The Unbroken", "Folded into the Long Night's Breath", "Clear waves of the risen in {city} without falling below half health", "TIID - Time. Alduin's second word gives the dead back the years the grave took, and it feeds on the wounded. Clear {n} whole waves of the risen in {city} without letting your health fall below half; bleed past it and that wave does not count.", { 1, 1, 2, 2, 2, 3 }, { 0, 0, 0, 0, 0, 0 } },
		TrialDef{ "steel", "Your Class's Trial", "The trial of your own class", "Win your class's trial in {city}", "The altar of {city} asks each who comes of their own craft. A Summoner, a conjurer of the College, lets the host make the kills (Pact of the Host); a Destruction mage, a College battle-mage, kills with two elements or more (Trial of the Elements); an Alchemist kills with flasks (Trial of the Crucible); a Spellsword of the Vigilants kills in melee with a spell in the other hand (Trial of Steel).", { 10, 12, 15, 20, 25, 30 }, { 0, 0, 0, 0, 0, 0 } },
		TrialDef{ "breath", "The Long Night's Breath", "Hold the altar while the waves are cleared", "Hold the Echo Altar of {city} through the night's waves", "VO - Undo. The last word undoes death itself, and the dead keep coming while it is spoken. Stand by the altar of {city} while the night's waves rise against it: clear {n} waves without straying from it, and its word is undone in turn. On Expert and above the Unbroken's rule holds too: a wave counts only if you never fell below half health.", { 1, 2, 2, 3, 3, 4 }, { 0, 0, 0, 0, 0, 0 } },
	} };
	enum TrialId : int { kTrial_ward = 0, kTrial_culling = 1, kTrial_unbroken = 2, kTrial_steel = 3, kTrial_breath = 4 };
	struct CityBoss { std::string_view name, row, text; float health; std::uint32_t weapon; std::string_view weaponName; };  // each city's Dragon Priest, the fourth step (health: in a zombie's night health); weapon: his drop (local id)
	inline constexpr std::array<CityBoss, 10> kCityBosses{ {
		CityBoss{ "Vahlok the Jailor", "priest_draugr", "Vahlok kept the cult's prisoners in the Merethic Era, and his oath to Alduin was the last he swore. It has brought him out of his tomb and across the sea to the barrow above Riverwood, to keep the valley's altar dark.", 20.0f, 0xE87, "Jailor's Keyhammer" },
		CityBoss{ "Nahkriin, Warden of Skuldafn", "priest_draman", "Nahkriin guarded Skuldafn, the gate to Sovngarde, for Alduin, and the mist that bars Sovngarde's door is his to keep. He has come down from the mountains to the plains, so that Whiterun's dead never find the way home.", 26.0f, 0xE88, "Mistblade" },
		CityBoss{ "Volsung of Volskygge", "priest_draugr2", "Volsung ruled the peaks above Haafingar from Volskygge, and his mask let him breathe where no man could. He climbs down to Solitude now, and the dead of the Blue Palace's crypts rise at his word.", 26.0f, 0xE89, "Windcutter" },
		CityBoss{ "Zahkriisos the Frost-Priest", "priest_draman2", "Zahkriisos lay in his tomb on Solstheim until Alduin's shout crossed the Sea of Ghosts. He walked over the ice to Windhelm's docks, and the cold he carries stops a heart.", 28.0f, 0xE8A, "Glacier Greatsword" },
		CityBoss{ "Otar the Mad", "priest_ancient", "Otar was so cruel that his own cult sealed him alive in Ragnvald. His oath to Alduin outlived his reason. He climbs out of the Reach's stone beneath Markarth to guard its altar.", 24.0f, 0xE8B, "Storm Blade" },
		CityBoss{ "Rahgot of Forelhost", "priest_draman_anc", "Rahgot's followers poisoned themselves in Forelhost rather than surrender him to the Tongues. They rise with him now, and the Rift's dead follow them down to Riften's altar.", 22.0f, 0xE8C, "Sacrifice Knife" },
		CityBoss{ "Krosis of Shearpoint", "priest_ancient2", "Krosis guarded the word at Shearpoint, mourning, for a thousand years. Alduin's shout gave him something to do with his sorrow: he comes down to Falkreath's graveyard to keep its children in the ground no longer.", 26.0f, 0xE8D, "Grief Blade" },
		CityBoss{ "Hevnoraak of Valthume", "priest_draman_anc2", "Hevnoraak's servants sealed him in Valthume to stop him rising. The seal could not hold against SLEN TIID VO: he walks out of the marsh fog, and Hjaalmarch's drowned dead follow him.", 24.0f, 0xE8E, "Sealbreaker" },
		CityBoss{ "Vokun of High Gate", "priest_mythic", "Vokun was a priest of shadows, and the Nightcaller's dreamers in Dawnstar dreamed his return a thousand years before it came. Kill him, and Dawnstar's nightmares end.", 22.0f, 0xE8F, "Nightcaller's Scythe" },
		CityBoss{ "Morokei of Labyrinthian", "priest_draman_myth", "Morokei once held the Staff of Magnus in Labyrinthian, and the College has feared him ever since. He has come to the cliffs above Winterhold, and the storm he calls has not finished yet.", 24.0f, 0xE90, "Arcane Maul" },
	} };
	inline constexpr std::uint32_t kCurseIntroGlobal = 0x996, kStandLayoutGlobal = 0x9DB, kDirgeBook = 0x9DC, kGuideBook = 0xC0A;
	inline constexpr std::string_view kCursePrologueTitle = "THE CURSE OF ALDUIN", kCursePrologue = "Helgen burned, and you lived. But Alduin did not flee: as he rose from the ash he shouted three words into the earth - SLEN TIID VO, Flesh, Time, Undo - the shout that raises the dead, and every barrow in Skyrim answered. His mist rolled over the door of Sovngarde, and now the dead of Skyrim cannot pass to Shor's hall: they lie restless in the ground, and when the sun goes down they claw their way up. The Dragon Priests who swore themselves to Alduin in the Merethic Era remember their oaths and wake with them. Only the Echo Altars the ancient Tongues raised in every hold can still his voice, and they have gone dark. Wake them, city by city, and their dead will sleep again.", kCurseLiftedBanner = "THE ECHO ALTAR OF {CITY} AWAKENS", kCurseLiftedText = "The altar of {city} rings with the old Tongues' answer, and Alduin's voice falls silent here. Its dead sleep again - none of the curse's dead will rise within its bounds.", kCurseFreedAll = "Every Echo Altar in Skyrim is awake. Alduin's voice lingers only in the wild places now - and in the echo he left on the Throat of the World.";
